import type { FullSchema, Record, SystemColumns, TableName } from '../db'
import type { Role } from './Role'

// refrences to sys_security_type
const AclRecordTypes = {
    pd_action: 'pd_action',
    record: 'record',
}

export const AclDataBrokerType = {
    ux_data_broker: '6d9c40e9531210101cb3ddeeff7b12f6',
}

/** @internal */
export const AclNamedTypes = {
    client_callable_flow_object: 'client_callable_flow_object',
    client_callable_script_include: 'client_callable_script_include',
    graphql: 'GraphQL',
    processor: 'processor',
    rest_endpoint: 'REST_Endpoint',
    ui_page: 'ui_page',
    ux_page: 'b9eb8a1b873303002941b53046cb0b18',
    ux_route: 'b9eb8a1b873303002941b53046cb1234',
}
/** @internal */
export const AclTypes = { ...AclRecordTypes, ...AclNamedTypes, ...AclDataBrokerType }

// references to sys_security_operation
/** @internal */
export const AclOperations = {
    execute: 'execute',
    create: 'create',
    read: 'read',
    write: 'write',
    delete: 'delete',
    conditional_table_query_range: '7aad4c50b7f4621062b62181ce11a918',
    data_fabric: 'e60cd19b4f602210f2c160cc32ce0b06',
    query_match: '521c7497b7300210240b06dd1e11a979',
    query_range: 'e66cf897b7300210240b06dd1e11a9fd',
    edit_task_relations: 'b718b0e2c0a80204005b2705d3b6a0a0',
    edit_ci_relations: 'b7199572c0a8020400ee6d907c07d6cc',
    save_as_template: 'e5a2b9c50a0a0bc5005dd4a3096ac37b',
    add_to_list: '394af8150a0a0b270096f5ac9d6bac47',
    report_on: 'f6861c32c0a8016400647951e901525d',
    list_edit: '54f535270a0a0b8c007c67009ab2bdc0',
    report_view: '0997ab83733303005978e4b9cdf6a7b9',
    personalize_choices: '76742c60c0a801657735f3789a7327d0',
}

// references to sys_security_attribute
/** @internal */
export const AclAttributes = {
    user_is_authenticated: '239bdf0c47d23110ba46ff58936d4330',
    has_admin_role: '8637f144b732111074f706dd1e11a981',
}
type AclType = keyof typeof AclTypes | (string & {})

type AclBase<Type extends AclType> = {
    /** Type of the resource being secured */
    type: Type
    /** Whether the ACL rule is enabled or not */
    active?: boolean
    /** The operation this ACL rule secures */
    operation: keyof typeof AclOperations | (string & {})
    /** Script that defines the permissions required to access the object */
    script?: ((current: any, ...dependencies: any[]) => boolean) | string
    /** Description of the object or permissions this ACL rule secures */
    description?: string
    /** Filter query specifying fields and values that must be true for access */
    condition?: string
    /** Array of roles that have access to the object */
    roles?: (string | Role)[]
    /** @deprecated Type of security attribute: 'Local' for condition-based or 'Existing' to reference an attribute */
    local_or_existing?: 'Local' | 'Existing'
    /** Type of security attribute: 'Local' for condition-based or 'Existing' to reference an attribute */
    localOrExisting?: 'Local' | 'Existing'
    /** @deprecated Whether the ACL should allow or deny access */
    decision_type?: 'allow' | 'deny'
    /** Whether the ACL should allow or deny access */
    decisionType?: 'allow' | 'deny'
    /** @deprecated Pre-defined conditions or security attributes to use for access control */
    security_attribute?: keyof typeof AclAttributes | (string & {}) | Record<'sys_security_attribute'>
    /** Pre-defined conditions or security attributes to use for access control */
    securityAttribute?: keyof typeof AclAttributes | (string & {}) | Record<'sys_security_attribute'>
    /** @deprecated Whether users with admin role automatically pass the permissions check for this ACL rule */
    admin_overrides?: boolean
    /** Whether users with admin role automatically pass the permissions check for this ACL rule */
    adminOverrides?: boolean
}

type AclByType<Type extends AclType, T extends TableName> = Type extends keyof typeof AclRecordTypes
    ? {
          /** The table this ACL rule applies to */
          table: T
          /** Optional field within the table to secure, or '*' for all fields */
          field?: keyof FullSchema<T> | SystemColumns | '*' | (string & {})
          /** @deprecated Additional filter to specify which records this ACL applies to */
          applies_to?: string
          /** Additional filter to specify which records this ACL applies to */
          appliesTo?: string
      }
    : Type extends Exclude<keyof typeof AclNamedTypes, 'ux_route' | 'ux_page'>
      ? {
            /** Name of the resource being secured */
            name: string
        }
      : Type extends keyof typeof AclDataBrokerType
        ? {
              /** Reference to the UX data broker this ACL applies to */
              dataBroker?: Record<'sys_ux_data_broker'> | string
              /** The table this ACL rule applies to */
              table?: T
              /** Optional field within the table to secure, or '*' for all fields */
              field?: keyof FullSchema<T> | SystemColumns | '*' | (string & {})
          }
        : {
              /** Name of the resource being secured */
              name?: string
              /** The table this ACL rule applies to */
              table?: T
              /** Optional field within the table to secure, or '*' for all fields */
              field?: keyof FullSchema<T> | SystemColumns | '*' | (string & {})
              /** @deprecated Additional filter to specify which records this ACL applies to */
              applies_to?: string
              /** Additional filter to specify which records this ACL applies to */
              appliesTo?: string
          }

/** @interface */
export type Acl<T extends TableName, Type extends AclType = AclType> = Now.Internal.WithIdAndMetadata<
    AclBase<Type> & AclByType<Type, T> & Now.Internal.Meta
>

/**
 * Creates an Access Control List (ACL) record that secure parts of an application (`sys_security_acl`).
 *
 * @param config - Configuration for the ACL record
 * @see https://docs.servicenow.com/csh?topicname=acl-api-now-ts.html&version=latest
 *
 * @example
 * ```ts
 * Acl({
 *     $id: Now.ID['incident_read'],
 *     type: 'record',
 *     table: 'incident',
 *     operation: 'read',
 * })
 * ```
 */
export function Acl<const Type extends AclType, const T extends TableName>(config: Acl<T, Type>) {
    return config
}
